SELECT MUST_CHANGE_PASSWORD
FROM TB_EMP
WHERE HOSP_DIV_ID = #{hospitalId}
  AND EMP_ID = #{userId}
  AND ROLE_CD = 'USER'

SELECT EMP_ID, EMP_PW, HOSP_DIV_ID, WARD_ID, EMP_NM,
       ROLE_CD, AUTH_ST, CRT_DT, UPD_DT,
       FAILED_LOGIN_COUNT, LOCKED_UNTIL
FROM TB_EMP
WHERE HOSP_DIV_ID = #{hospitalId}
  AND EMP_ID = #{userId}
